// Bad example: Improper use of the Java JDBC API in a web application.
// vulnerable: user input is concatenated directly into SQL, allowing SQL injection.
import java.sql.*;
import java.io.*;
import java.util.*;

public class BadWebAppExample {
    public String getUser(String username) throws Exception {
        String sql = "SELECT * FROM users WHERE username = '" + username + "'";
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/app", "user", "pass");
        Statement stmt = conn.createStatement();
        ResultSet rs = stmt.executeQuery(sql);

        if (rs.next()) {
            return rs.getString("email");
        }

        return "Not found";
    }
}
***
// Good example: Use PreparedStatement to safely bind user input.
// This prevents SQL injection by separating code and data.
import java.sql.*;

public class GoodWebAppExample {
    public String getUser(String username) throws Exception {
        String sql = "SELECT * FROM users WHERE username = ?";
        try (
            Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/app", "user", "pass");
            PreparedStatement pstmt = conn.prepareStatement(sql)
        ) {
            pstmt.setString(1, username);

            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    return rs.getString("email");
                }
            }
        }

        return "Not found";
    }
}

